module cascaded_adder #(
    parameter int IN_DATA_WIDTH = 16,                       // Width of each input data
    parameter int IN_DATA_NS = 4,                           // Number of input data elements
    parameter int NUM_STAGES = $clog2(IN_DATA_NS),          // Number of summation stages (calculated once)
    parameter logic [NUM_STAGES-1:0] REG = {NUM_STAGES{1'b1}}  // Control bits for register insertion
) (
   input  logic clk,
   input  logic rst_n,
   input  logic i_valid, 
   input  logic [IN_DATA_WIDTH*IN_DATA_NS-1:0] i_data,  // Flattened input data array
   output logic o_valid,
   output logic [(IN_DATA_WIDTH+$clog2(IN_DATA_NS))-1:0] o_data // Output data (sum)
);

   // Internal signals for the adder tree
   logic [IN_DATA_WIDTH*IN_DATA_NS-1:0] i_data_ff;                             // Flattened input data array register
   logic [IN_DATA_WIDTH-1:0] in_data_2d [IN_DATA_NS-1:0];                      // Intermediate 2D array
   wire [(IN_DATA_WIDTH+$clog2(IN_DATA_NS))-1:0] stage_output [NUM_STAGES-1:0][(IN_DATA_NS/2)-1:0];
   logic valid_ff;
   wire valid_pipeline [NUM_STAGES-1:0];  // Pipeline to handle the valid signal latencies based on REG

   // Register the input data on valid signal
   always_ff @(posedge clk or negedge rst_n) begin : reg_indata
      if(!rst_n)
         i_data_ff <= 0;
      else begin
         if(i_valid) begin
            i_data_ff <= i_data;
         end
      end
   end

   // Convert flattened input to 2D array
   always_comb begin
       for (int i = 0; i < IN_DATA_NS; i++) begin : conv_1d_to_2d
           in_data_2d[i] = i_data_ff[(i+1)*IN_DATA_WIDTH-1 -: IN_DATA_WIDTH];
       end
   end

   generate for(genvar st=0;st<NUM_STAGES;st=st+1)begin: stages
 for(genvar p=0;p<(IN_DATA_NS>>(st+1));p=p+1)begin: pairs
 wire [IN_DATA_WIDTH+NUM_STAGES-1:0] v;
 if(st==0)assign v={1'b0,in_data_2d[2*p]}+{1'b0,in_data_2d[2*p+1]};
 else assign v=stage_output[st-1][2*p]+stage_output[st-1][2*p+1];
 if(REG[st])begin reg [IN_DATA_WIDTH+NUM_STAGES-1:0] q;always_ff @(posedge clk or negedge rst_n)if(!rst_n)q<=0;else q<=v;assign stage_output[st][p]=q;end
 else assign stage_output[st][p]=v;
 end
end endgenerate


   always_ff @(posedge clk or negedge rst_n) begin
      if(!rst_n)
         valid_ff <= 1'b0;
      else 
         valid_ff <= i_valid;
   end


   generate for(genvar st=0;st<NUM_STAGES;st=st+1)begin: valids
 wire v;if(st==0)assign v=valid_ff;else assign v=valid_pipeline[st-1];
 if(REG[st])begin reg q;always_ff @(posedge clk or negedge rst_n)if(!rst_n)q<=0;else q<=v;assign valid_pipeline[st]=q;end
 else assign valid_pipeline[st]=v;
end endgenerate


   // Assign the final stage of valid_pipeline to o_valid
   always_ff @(posedge clk or negedge rst_n) begin
      if(!rst_n)
         o_valid <= 1'b0;
      else
         o_valid <= valid_pipeline[NUM_STAGES-1];
   end

   // Output data assignment
   always_ff @(posedge clk or negedge rst_n) begin : reg_outdata
      if ( !rst_n) begin
         o_data <= 0 ;
      end else if (valid_pipeline[NUM_STAGES-1]) begin
         o_data <= stage_output[NUM_STAGES-1][0];
      end
   end

endmodule

module cvdp_copilot_perf_counters #(parameter CNT_W=8)(input clk,reset,sw_req_i,cpu_trig_i,output [CNT_W-1:0] p_count_o);
reg [CNT_W-1:0] count_q;assign p_count_o=sw_req_i?count_q:0;
always @(posedge clk or posedge reset)if(reset)count_q<=0;else if(sw_req_i)count_q<=cpu_trig_i;else if(cpu_trig_i)count_q<=count_q+1'b1;endmodule

module thermostat(input i_clk,i_rst,input [5:0] i_temp_feedback,input i_fan_on,i_enable,i_fault,i_clr,output reg o_heater_full,o_heater_medium,o_heater_low,o_aircon_full,o_aircon_medium,o_aircon_low,o_fan,output reg [2:0] o_state);
reg fault_latched;reg [2:0] target;
always @*begin target=3;if(i_temp_feedback[5])target=2;else if(i_temp_feedback[4])target=1;else if(i_temp_feedback[3])target=0;else if(i_temp_feedback[0])target=6;else if(i_temp_feedback[1])target=5;else if(i_temp_feedback[2])target=4;end
always @(posedge i_clk or negedge i_rst)if(!i_rst)begin o_state<=3;fault_latched<=0;o_heater_full<=0;o_heater_medium<=0;o_heater_low<=0;o_aircon_full<=0;o_aircon_medium<=0;o_aircon_low<=0;o_fan<=0;end else begin
if(i_fault)fault_latched<=1;else if(i_clr)fault_latched<=0;
o_state<=3;o_heater_full<=0;o_heater_medium<=0;o_heater_low<=0;o_aircon_full<=0;o_aircon_medium<=0;o_aircon_low<=0;o_fan<=0;
if(i_enable&&!i_fault&&!fault_latched&&!i_clr)begin o_state<=target;o_heater_full<=target==2;o_heater_medium<=target==1;o_heater_low<=target==0;o_aircon_full<=target==6;o_aircon_medium<=target==5;o_aircon_low<=target==4;o_fan<=i_fan_on||(target!=3);end end endmodule

module ttc_counter_lite(input clk,reset,input [3:0] axi_addr,input [31:0] axi_wdata,input axi_write_en,axi_read_en,output reg [31:0] axi_rdata,output reg interrupt);
reg [15:0] count,match_value,reload_value;reg [2:0] control_reg;wire enable=control_reg[0],interval_mode=control_reg[1],interrupt_enable=control_reg[2];
always @(posedge clk or posedge reset)if(reset)begin count<=0;match_value<=0;reload_value<=0;control_reg<=0;interrupt<=0;end else begin
if(control_reg[0])begin if(count==match_value)begin if(control_reg[2])interrupt<=1;if(control_reg[1])count<=reload_value;end else count<=count+1'b1;end
if(axi_write_en)case(axi_addr)1:match_value<=axi_wdata[15:0];2:reload_value<=axi_wdata[15:0];3:control_reg<=axi_wdata[2:0];4:interrupt<=0;default:;endcase end
always @*begin axi_rdata=0;case(axi_addr)0:axi_rdata={16'b0,count};1:axi_rdata={16'b0,match_value};2:axi_rdata={16'b0,reload_value};3:axi_rdata={29'b0,control_reg};4:axi_rdata={31'b0,interrupt};default:axi_rdata=0;endcase end endmodule
